import math

def tau(n):
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

min_a = float('inf')
found_solutions = []

# Search range for n: 1 <= n <= 1000
for n in range(1, 1001):
    n_plus_735 = n + 735

    tau_n = tau(n)
    tau_n_plus_735 = tau(n_plus_735)

    if tau_n == tau_n_plus_735:
        K = tau_n
        a = K - 2

        if a >= 0: # d(n) must be non-negative
            found_solutions.append((n, K, a))
            if a < min_a:
                min_a = a

print(f"Found solutions: {found_solutions}")
print(f"Minimum value of d(n) found (a): {min_a}")

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

print(is_prime(743))
